import {revisionModes,createRevision,editParagraph,acceptParagraph,revisedText,snapshot,restoreVersion,difference} from './revision-model.mjs';
import {keys,list,write,projects,recordTask} from './state.mjs';
import {esc,icon,formatDate,download} from './ui.mjs';
const $=s=>document.querySelector(s),saved=()=>list(keys.drafts).filter(d=>d.revision),name=mode=>revisionModes.find(m=>m[0]===mode)?.[1]||'修改稿';
let context,doc=null,index=0,mode='review',dirty=false,controller;
const now=()=>new Date().toISOString();
function confirmLeave(){return !dirty||window.confirm('有尚未保存的修改，离开后会丢失这些修改。仍要离开吗？');}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a||!$('#revision-space')||!dirty||a.href===location.href)return;if(!confirmLeave()){e.preventDefault();e.stopImmediatePropagation();}else dirty=false;},true);
const heading=()=>`<div class="hub-heading"><div><h1>修改与润色</h1><p>从导师意见到逐段修改，让每一次修改都有记录。</p></div><div class="hub-heading-actions"><button class="btn secondary" data-rev-action="existing">${icon('folder',17)}选择已有成果</button><button class="btn primary" data-rev-action="new">${icon('upload',17)}导入论文</button></div></div>`;
function save(label='保存修改',fromEditor=true){if(!doc)return false;try{if(fromEditor)capture();const next=snapshot(doc,crypto.randomUUID(),now(),label),rows=list(keys.drafts),at=rows.findIndex(d=>String(d.id)===next.id);if(at<0)rows.unshift(next);else rows[at]=next;write(keys.drafts,rows);doc=next;dirty=false;try{recordTask({id:'draft-'+doc.id,title:doc.title,kind:'本地修改稿保存',projectId:doc.projectId,url:'#draft/'+doc.id,status:'record'});}catch{context.notify('修改稿已保存，但操作记录未能保存。');}context.notify('版本已保存，原稿和历史版本均保留。');draw();return true;}catch(e){context.notify(e.message||'保存失败，请检查浏览器空间并导出备份。');return false;}}
function capture(){if(!doc||!$('#rev-suggestion'))return;const p=doc.paragraphs[index],patch={suggestion:$('#rev-suggestion').value,reason:$('#rev-reason').value,comment:$('#rev-comment').value,resolved:$('#rev-resolved').checked};if(Object.keys(patch).some(k=>patch[k]!==p[k])){doc=editParagraph(doc,index,patch);dirty=true;}}
function diffMarkup(a,b){const d=difference(a,b);return `<div class="rev-diff-grid"><div><b>原文变化区间</b><p>${esc(d.prefix)}<del>${esc(d.removed)}</del>${esc(d.suffix)}</p></div><div><b>修改稿变化区间</b><p>${esc(d.prefix)}<ins>${esc(d.added)}</ins>${esc(d.suffix)}</p></div></div><p class="hub-footnote">按共同前缀与后缀标记变化区间；这是文本对照，不是查重或 AI 检测结果。</p>`;}
export function revisionRouteGuard(){if(!dirty||!$('#revision-space'))return true;if(!confirmLeave())return false;dirty=false;return true;}
export function mountRevision(options,id){context=options;if(options.mode)mode=options.mode;controller?.abort();controller=new AbortController();if(id){let key=id;try{key=decodeURIComponent(id);}catch{}doc=saved().find(d=>String(d.id)===key)||null;mode=doc?.mode||mode;index=0;dirty=false;}else if(!dirty){doc=null;index=0;}draw();$('.dashboard').addEventListener('click',handle,{signal:controller.signal});$('.dashboard').addEventListener('input',e=>{if(e.target.closest('#rev-edit-form')){dirty=true;$('#rev-save-state').textContent='尚未保存 · 请保存版本';}},{signal:controller.signal});}
function draw(){const rows=saved().sort((a,b)=>Date.parse(b.updatedAt)-Date.parse(a.updatedAt)),p=doc?.paragraphs[index];$('.dashboard').innerHTML=heading()+`<div id="revision-space"><nav class="rev-modes" aria-label="修改任务">${revisionModes.map(([key,label,desc])=>`<button data-rev-mode="${key}" aria-pressed="${mode===key}" class="${mode===key?'selected':''}">${icon(key==='review'?'user':key==='reduce'?'shield':'pen',22)}<span><b>${label}</b><small>${desc}</small></span></button>`).join('')}</nav><div class="rev-layout"><div><section class="card rev-main"><header><h2>修改工作空间</h2><span class="rev-chip">${doc?'手动修改':'开始新修改'}</span></header><ol class="rev-steps">${['导入原文','明确要求','对照修改','确认与导出'].map((n,i)=>`<li class="${doc?i===2?'active':'':i===0?'active':''}"><span>${i+1}</span>${n}</li>`).join('')}</ol>${doc?`<div class="rev-document"><div><b>${esc(doc.title)}</b><small>${esc(projects().find(p=>p.id===doc.projectId)?.name||'未归入项目')} · ${esc(name(doc.mode))} · ${doc.paragraphs.length} 段</small></div><button class="btn secondary" data-rev-action="requirements">编辑要求</button></div><p class="rev-requirements">修改要求：${esc(doc.requirements||'尚未填写')}</p>${doc.warnings?.length?`<details class="rev-notice"><summary>导入提示（${doc.warnings.length}）</summary>${doc.warnings.map(w=>`<p>${esc(w)}</p>`).join('')}</details>`:''}<div class="rev-toolbar"><label for="rev-paragraph">选择段落</label><select id="rev-paragraph">${doc.paragraphs.map((p,i)=>`<option value="${i}" ${i===index?'selected':''}>第 ${i+1} 段 · ${p.accepted?'已采纳':p.suggestion!==p.original?'待采纳':'原文'} — ${esc(p.original.slice(0,22))}</option>`).join('')}</select><button class="btn secondary" data-rev-action="diff">查看差异</button></div><form id="rev-edit-form"><div class="rev-editors"><section><h3>原文 <span>只读</span></h3><pre>${esc(p.original)}</pre></section><section><h3>修改稿 <span>${p.accepted?'已采纳':'手动编辑 · 待确认'}</span></h3><label class="sr-only" for="rev-suggestion">编辑当前段修改稿</label><textarea id="rev-suggestion" maxlength="20000">${esc(p.suggestion)}</textarea></section></div><div class="rev-comments"><div><label for="rev-comment">导师意见 / 待核对问题</label><textarea id="rev-comment" maxlength="2000" rows="2" placeholder="记录这段需要解决的问题…">${esc(p.comment)}</textarea></div><div><label for="rev-reason">修改说明</label><textarea id="rev-reason" maxlength="2000" rows="2" placeholder="记录修改原因与需要核对的依据…">${esc(p.reason)}</textarea></div></div><label class="rev-resolved"><input type="checkbox" id="rev-resolved" ${p.resolved?'checked':''}> 我已核对并解决本段意见（独立于是否采纳）</label></form><div class="rev-accept"><span>采纳后才会进入导出稿；继续编辑需重新确认。</span><button class="btn secondary" data-rev-action="keep">保留原文</button><button class="btn secondary" data-rev-action="accept">采纳本段</button></div><div class="rev-footer"><span id="rev-save-state" role="status">${dirty?'尚未保存 · 请保存版本':'已保存版本 · 本地浏览器'}</span><button class="btn secondary" data-rev-action="save">保存版本</button><button class="btn primary" data-rev-action="export">确认与导出</button></div>`:`<div class="rev-empty"><div class="rev-empty-icon">${icon('pen',34)}</div><h3>开始修改你的论文</h3><p>导入有权使用的论文，填写修改要求，逐段编辑和核对。</p><button class="btn primary" data-rev-action="new">${icon('plus',16)}创建修改稿</button><button class="btn secondary" data-rev-action="existing">选择已有成果</button><small>支持 DOCX / PDF / TXT 或粘贴正文；不会自动生成修改。</small></div>`}<p class="rev-notice">${mode==='reduce'?'表达优化不保证降低 AI 检测分数或通过检测，不生成推测的 AI 率。':mode==='rewrite'?'请结合真实相似来源与规范引用核对；未重新检测时不生成新的重复率。':'修改需核对引用、数据、公式和研究结论，不能用润色替代研究证据。'}</p></section><section class="card rev-versions"><header><h2>版本记录</h2>${doc?'<button class="btn secondary" data-rev-action="backup">导出完整备份</button>':''}</header>${doc?`<div class="rev-version-row"><b>原始导入文稿</b><span>${esc(formatDate(doc.createdAt))}</span><button data-rev-action="original">查看原稿</button><button data-rev-action="reset">恢复原稿</button></div>${doc.versions.slice().reverse().map((v,i)=>`<div class="rev-version-row"><b>v${doc.versions.length-i} · ${esc(v.label)}</b><span>${esc(formatDate(v.at))}</span><button data-rev-version="${esc(v.id)}">查看与恢复</button></div>`).join('')}`:'<p class="hub-footnote">创建文稿后，原稿与每次主动保存的版本会保留在这里。</p>'}</section></div><aside class="rev-side"><section class="card"><h2>最近修改</h2>${rows.length?rows.slice(0,4).map(r=>`<a href="#draft/${encodeURIComponent(r.id)}"><b>${esc(r.title)}</b><small>${esc(name(r.mode))} · ${esc(formatDate(r.updatedAt))}</small><span>继续修改 →</span></a>`).join(''):'<p>尚无修改记录。创建并保存第一份修改稿后，会显示在这里。</p>'}</section><section class="card"><h2>待核对意见</h2>${doc?doc.paragraphs.filter(p=>p.comment&&!p.resolved).map(p=>`<button class="rev-issue" data-rev-jump="${doc.paragraphs.indexOf(p)}"><b>第 ${doc.paragraphs.indexOf(p)+1} 段</b><span>${esc(p.comment.slice(0,100))}</span></button>`).join('')||'<p>暂无待核对意见。是否解决由你单独确认，采纳修改不会自动标记解决。</p>':'<p>在段落中记录导师意见与问题，方便定位修改。</p>'}</section><section class="card"><h2>当前能力</h2><p>本地编辑、逐段对照、版本保存与 TXT 导出。</p><div class="rev-notice">AI 修改尚未接入。当前不生成建议稿、重复率或 AI 率。</div><p>原始文件不保存，Word 排版与批注不会保留。请及时备份。</p></section></aside></div></div>`;
$('#rev-paragraph')?.addEventListener('change',e=>{const next=Number(e.target.value);try{capture();index=next;draw();}catch(err){context.notify(err.message);e.target.value=index;}});}
function handle(e){const b=e.target.closest('[data-rev-action],[data-rev-mode],[data-rev-version],[data-rev-jump]');if(!b)return;try{if(b.dataset.revMode){if(!confirmLeave())return;mode=b.dataset.revMode;doc=null;dirty=false;draw();return;}capture();if(b.dataset.revJump){index=Number(b.dataset.revJump);draw();return;}if(b.dataset.revVersion){versionDialog(b.dataset.revVersion);return;}switch(b.dataset.revAction){case'new':if(confirmLeave())inputForm();break;case'existing':if(confirmLeave())existingDialog();break;case'requirements':requirementsForm();break;case'save':save();break;case'accept':doc=acceptParagraph(doc,index);dirty=true;draw();break;case'keep':doc=editParagraph(doc,index,{accepted:false});dirty=true;draw();break;case'diff':context.modal('当前段落差异',diffMarkup(doc.paragraphs[index].original,doc.paragraphs[index].suggestion));break;case'export':exportDialog();break;case'backup':download(doc.title+'-修改备份.json',JSON.stringify({format:'paperknow-revision-backup',version:1,document:doc},null,2),'application/json');context.notify('已发起备份下载，包含当前编辑和历史版本。');break;case'original':context.modal('原始导入文稿',`<pre class="rev-preview">${esc(doc.original)}</pre>`);break;case'reset':{context.modal('恢复原稿',`<p>将原始导入文本恢复为当前稿，并保存新的版本。当前编辑也会先保存，历史不会覆盖。</p><button class="btn primary" id="rev-reset-confirm">恢复并保存新版本</button>`);$('#rev-reset-confirm').onclick=()=>{if(doc.versions.length>48){context.notify('剩余版本空间不足，请导出备份。');return;}if(!save('恢复前保存'))return;const base=createRevision({...doc,text:doc.original},doc.id,doc.createdAt);doc={...doc,paragraphs:base.paragraphs};dirty=true;draw();if(save('恢复原稿',false))$('#workspace-dialog').close();};break;}}}catch(err){context.notify(err.message||'操作失败，请保留原稿并重试。');}}
function fields(values={}){return `<label for="rev-title">文稿标题 *</label><input id="rev-title" maxlength="200" required value="${esc(values.title||'')}"><label for="rev-project">所属项目</label><select id="rev-project"><option value="">未归入项目</option>${projects().map(p=>`<option value="${esc(p.id)}" ${p.id===values.projectId?'selected':''}>${esc(p.name)}</option>`).join('')}</select><label for="rev-requirements">修改要求 / 导师意见</label><textarea id="rev-requirements" rows="3" maxlength="5000" placeholder="填写修改目标；降重时请记录真实来源或报告位置…">${esc(values.requirements||'')}</textarea>`;}
function inputForm(source={}){let fileName='',warnings=[],busy=false;context.modal('创建'+name(mode)+'任务',`<form id="rev-create" class="hub-form">${fields(source)}<label class="lit-upload" for="rev-file">${icon('upload',20)}<span>选择文档（可选）<small> DOCX / PDF / TXT · 最大 50MB</small></span><input id="rev-file" type="file" accept=".docx,.pdf,.txt"></label><p id="rev-file-status" role="status"></p><label for="rev-input-text">论文正文 *</label><textarea id="rev-input-text" rows="8" maxlength="100000" required placeholder="粘贴正文，用空行分隔段落；最多 100,000 字符。">${esc(source.text||'')}</textarea><p class="hub-footnote">仅提取文本，不保留原始文件、排版和批注；扫描 PDF 不支持 OCR。正文不会上传，AI 尚未接入。</p><p id="rev-form-error" role="alert"></p><button class="btn primary" id="rev-create-submit">创建并保存原稿</button></form>`);const form=$('#rev-create');$('#rev-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>50*1024*1024){$('#rev-file-status').textContent='文件超过 50MB。';return;}if($('#rev-input-text').value.trim()&&!window.confirm('导入会替换表单中的正文，是否继续？'))return;busy=true;$('#rev-create-submit').disabled=true;$('#rev-file-status').textContent='正在本地解析…';try{const {extractFile}=await import('/precheck/assets/parsers.js');const result=await extractFile(file);if($('#rev-create')!==form)return;if(!result.text.trim())throw Error('未提取到正文，请核对文件或粘贴文本。');if(result.text.length>100000)throw Error('正文超过 100,000 字符，请分章节导入。');$('#rev-input-text').value=result.text;fileName=file.name;warnings=result.warnings||[];if(!$('#rev-title').value.trim())$('#rev-title').value=file.name.replace(/\.[^.]+$/,'').slice(0,200);$('#rev-file-status').textContent=`已提取 ${result.text.length} 字符，请核对正文。${warnings.length?'存在 '+warnings.length+' 条解析提示，创建后可查看。':''}`;}catch(err){if($('#rev-create')===form)$('#rev-file-status').textContent=err.message;}finally{busy=false;if($('#rev-create')===form)$('#rev-create-submit').disabled=false;}};
form.onsubmit=e=>{e.preventDefault();if(busy)return;const old=doc;try{const next=createRevision({title:$('#rev-title').value,text:$('#rev-input-text').value,requirements:$('#rev-requirements').value,projectId:$('#rev-project').value,mode,fileName,warnings,sourceId:source.id||''},crypto.randomUUID(),now());doc=next;index=0;if(save('原稿导入',false))$('#workspace-dialog').close();else doc=old;}catch(err){doc=old;$('#rev-form-error').textContent=err.message;}};}
function existingDialog(){const rows=list(keys.drafts).filter(d=>!d.revision&&String(d.text||'').trim());context.modal('选择已有成果',`<p>复制已有成果文本创建修改稿，原成果不会被覆盖。结构模板也需先核对是否包含正文。</p>${rows.length?`<div class="rev-existing">${rows.map((d,i)=>`<button data-rev-existing="${i}"><b>${esc(d.title||'未命名成果')}</b><small>${esc(formatDate(d.updatedAt))}</small></button>`).join('')}</div>`:'<p>尚无可复制的正文成果，请导入文档或粘贴正文。</p>'}`);$('#workspace-dialog-body').querySelectorAll('[data-rev-existing]').forEach(b=>b.onclick=()=>inputForm(rows[Number(b.dataset.revExisting)]));}
function requirementsForm(){context.modal('编辑修改要求',`<form id="rev-meta" class="hub-form">${fields(doc)}<button class="btn primary">应用到当前稿</button><p>应用后仍需保存版本。</p></form>`);$('#rev-meta').onsubmit=e=>{e.preventDefault();const title=$('#rev-title').value.trim();if(!title)return;doc={...doc,title,projectId:$('#rev-project').value,requirements:$('#rev-requirements').value};dirty=true;$('#workspace-dialog').close();draw();};}
function versionDialog(id){const v=doc.versions.find(v=>v.id===id);if(!v)return;context.modal('版本内容与恢复',`<p>${esc(v.label)} · ${esc(formatDate(v.at))}</p><pre class="rev-preview">${esc(revisedText(v))}</pre><p>恢复会先保存当前稿，再添加一个恢复版本，不覆盖历史。</p><button class="btn primary" id="rev-restore">恢复此版本</button>`);$('#rev-restore').onclick=()=>{if(doc.versions.length>48){context.notify('剩余版本空间不足，请导出备份。');return;}if(!save('恢复前保存'))return;doc=restoreVersion(doc,id);dirty=true;draw();if(save('恢复历史版本',false))$('#workspace-dialog').close();};}
function exportDialog(){const text=revisedText(doc),accepted=doc.paragraphs.filter(p=>p.accepted).length;context.modal('确认与导出',`<p>已采纳 ${accepted} / ${doc.paragraphs.length} 段。未采纳段落使用原文。请核对引用、数据和研究结论。</p><pre class="rev-preview">${esc(text)}</pre><button class="btn primary" id="rev-export-confirm">保存版本并导出 TXT</button><p class="hub-footnote">段落以空行分隔；不包含 Word 排版、批注或修订痕迹。</p>`);$('#rev-export-confirm').onclick=()=>{if(!save('确认导出'))return;download(doc.title+'-修改稿.txt',revisedText(doc));$('#workspace-dialog').close();context.notify('已发起 TXT 下载，请确认浏览器保存。');};}
